import re

PATTERN = re.compile(r'[STFG][0-9]{7}[A-Z]')   # [0-9], not \d: \d also matches Unicode digits
WEIGHTS = (2, 7, 6, 5, 4, 3, 2)
OFFSET = {'S': 0, 'T': 4, 'F': 0, 'G': 4}
LETTERS = {'S': 'JZIHGFEDCBA', 'T': 'JZIHGFEDCBA',
           'F': 'XWUTRQPNMLK', 'G': 'XWUTRQPNMLK'}

def is_valid(raw):
    s = raw.strip().upper()
    if not PATTERN.fullmatch(s):          # shape first: prefix, 7 digits, letter
        return False
    total = OFFSET[s[0]]
    for digit, weight in zip(s[1:8], WEIGHTS):
        total += int(digit) * weight
    return s[8] == LETTERS[s[0]][total % 11]

def solution(ids):
    return [is_valid(raw) for raw in ids]

